# Kaggle CPU; no datasets, training, or model forecasts. Downloads only the frozen public code.
import base64,hashlib,os,subprocess,sys,zlib
from pathlib import Path
rev="66fb39d2de3df280ac831a4b5a0c0f095f1a0779"; repo=Path("/tmp/pinns_graph_init_src_"+rev[:12])
subprocess.run(["git","init","-q",str(repo)],check=True)
subprocess.run(["git","-C",str(repo),"fetch","-q","--depth=1","https://github.com/pjyyyds/Unstructured-ShortPose-Pred.git",rev],check=True)
subprocess.run(["git","-C",str(repo),"checkout","--detach","-q",rev],check=True)
d=Path("/tmp/pinns_graph_init_verify");d.mkdir(exist_ok=True)
def restore(name,h,enc):
    data=zlib.decompress(base64.b64decode(enc))
    if hashlib.sha256(data).hexdigest()!=h:raise ValueError("Changed "+name)
    (d/name).write_bytes(data)
restore('reconstruct_initialization.py','f88f069fe70f534e33a2e26d918046bc0626af73f6ba4e7fd136619e301d4640','')
restore('initialization_reference.json','111933bb82856df60cf27f0718aef70b00890ce083f78dd087523b043de96250','')
env={**os.environ,"PYTHONPATH":str(repo),"CUDA_VISIBLE_DEVICES":"","OMP_NUM_THREADS":"4","MKL_NUM_THREADS":"4","OPENBLAS_NUM_THREADS":"1"}
subprocess.run([sys.executable,"-u",str(d/"reconstruct_initialization.py"),str(repo),str(d/"initialization_reference.json"),"/kaggle/working/graph_initialization_replay.zip"],cwd=repo,env=env,check=True)
